<script lang="ts">
 import {enhance} from '$app/forms';import AppHeader from '#lib/components/AppHeader.svelte';import UserAvatar from '#lib/components/UserAvatar.svelte';import NewPassword from '#lib/components/NewPassword.svelte';import PasswordInput from '#lib/components/PasswordInput.svelte';
 import ArrowLeft from 'phosphor-svelte/lib/ArrowLeftIcon';
 let {data,form}=$props();let pending=$state(''),password=$state(''),confirmation=$state('');
 const validPassword=$derived(password.length>=8&&password.length<=128&&password===confirmation);
</script>
<svelte:head><title>Lisière | Paramètres</title></svelte:head>
<div class="settings-page"><AppHeader user={data.user} showSearch={false} settings/>
 <main class="settings-main"><a class="back-link" href="/"><ArrowLeft size={16}/>Retour à la carte</a><div class="settings-heading"><div><h1>Paramètres</h1><p>Votre profil et la sécurité de votre compte.</p></div><UserAvatar user={data.user} size={56}/></div>
 {#if data.emailConfirmed}<p class="settings-message success" role="status">Adresse e-mail confirmée.</p>{/if}{#if data.emailPending}<p class="settings-message success" role="status">Un lien de confirmation a été envoyé à votre nouvelle adresse.</p>{/if}{#if data.verificationError}<p class="settings-message error" role="alert">Le lien de confirmation est invalide ou a expiré. Faites une nouvelle demande.</p>{/if}
