  <div class="settings-grid"><div><label class="label" for="profile-first">Prénom</label><input class="input" id="profile-first" name="firstName" value={data.user.firstName} maxlength="80" autocomplete="given-name"/></div><div><label class="label" for="profile-last">Nom</label><input class="input" id="profile-last" name="lastName" value={data.user.lastName} maxlength="80" autocomplete="family-name"/></div></div>
  {#if form?.section==='profile'}{#if form.error}<p class="error" role="alert">{form.error}</p>{:else if form.success}<p class="success" role="status">{form.success}</p>{/if}{/if}
  <button class="btn settings-submit" disabled={!!pending}>{pending==='profile'?'Enregistrement…':'Enregistrer le profil'}</button>
 </form></section>
 <section class="card settings-section" aria-labelledby="email-heading"><div class="section-intro"><h2 id="email-heading">Adresse e-mail</h2><p>Adresse actuelle : <span>{data.user.email}</span></p></div><form method="POST" action="?/email" use:enhance={()=>{pending='email';return async({update})=>{await update({reset:false});pending='';};}}>
  <label class="label" for="new-email">Nouvelle adresse e-mail</label><input class="input" id="new-email" name="email" type="email" required maxlength="254" autocomplete="email" placeholder="nom@exemple.fr"/>
  <PasswordInput id="email-current-password"/>
  <p class="field-note">Le changement prend effet après confirmation par e-mail.</p>
  {#if form?.section==='email'}{#if form.error}<p class="error" role="alert">{form.error}</p>{:else if form.success}<p class="success" role="status">{form.success}</p>{/if}{/if}
  <button class="btn settings-submit" disabled={!!pending}>{pending==='email'?'Envoi…':'Confirmer le changement'}</button>
 </form></section>
 <section class="card settings-section" aria-labelledby="password-heading"><div class="section-intro"><h2 id="password-heading">Mot de passe</h2><p>Les autres sessions seront déconnectées après la modification.</p></div><form method="POST" action="?/password" use:enhance={()=>{pending='password';return async({result,update})=>{await update({reset:result.type==='success'});if(result.type==='success'){password='';confirmation='';}pending='';};}}>
  <PasswordInput id="password-current"/><NewPassword bind:password bind:confirmation/>
  {#if form?.section==='password'}{#if form.error}<p class="error" role="alert">{form.error}</p>{:else if form.success}<p class="success" role="status">{form.success}</p>{/if}{/if}
  <button class="btn settings-submit" disabled={!!pending||!validPassword}>{pending==='password'?'Enregistrement…':'Modifier le mot de passe'}</button>
 </form></section>
 </main></div>
